#!/bin/bash

# Create note
echo "1/11 Creating note no title"
curl -X POST -s \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer $TOKEN" \
  http://localhost:8585/rest/notes \
  -d '{
    "description": "note content from shell script testing api",
    "url": "https://gentoo.org",
    "tags": ["bash", "test"]
  }' | jq

